head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


rownum = 0;
/**
 * @method
 * @name file_browse
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.file_browse = function() {
    var fileCnt = $("input[name=file_coment]").length;
    if (fileCnt >= 5) {
        alert("파일업로드는 5개까지만 가능합니다.");
        return;
    } else {
        scwin.fn_addRow();
    }
};



//파일명 추출후 업로드 가능 확장자인지 확인.
/**
 * @method
 * @name fn_getFileNm
 * @description desc
 * @param {string} rn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm = function(rn) {
    var objFile = $("input[name='attachFiles[" + rn + "]']");
    var temp = objFile.val();
    var file_name = temp.substring(temp.lastIndexOf('\\') + 1);
    var file = file_name.split(".");
    var temp = $("input[name='attachFiles[" + rn + "]']").val(); //원본파일
    var temp2 = temp.substring(temp.lastIndexOf('\\') + 1); //파일명 확장자포함
    var temp3 = temp2.substring(temp2.lastIndexOf('.') + 1); //확장자
    var temp4 = temp2.substring(0, temp2.lastIndexOf('.')); //파일명만

    // DART Viewer 지원 중지로 dsd 파일 업로드 불가 2024.05.16 by 김효준
    var extList = new Array("hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "gif", "jpg", "jpeg", "bmp", "tif", "txt", "drt", "png");
    var fileChk = 0;
    for (var i = 0; i < extList.length; i++) {
        if (file[file.length - 1].toLowerCase() == extList[i]) fileChk = fileChk + 1;
    }
    if (fileChk == 0) {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='attachFiles[" + rn + "]']").val("");
        $("input[name='attach_file_nm[" + rn + "]']").val("");
        objFile.replaceWith(objFile.clone(true));
        return;
    }

    //파일명 길이체크
    //alert(file[file.length-2].length);
    if (temp4.length > 35) {
        alert("파일명이 35자를 초과하는 파일은 첨부 할 수 없습니다.");
        $("input[name='attach_file_nm[" + rn + "]']").val("");
        objFile.replaceWith(objFile.clone(true));
        return;
    }

    // 중복파일 체크.
    var fileCnt = $("input[name=file_coment]").length;
    for (var i = 0; i < fileCnt; i++) {
        if (file_name == $("input[name='attach_file_nm[" + i + "]']").val()) {
            alert("이미 첨부된 파일입니다.");
            //$("input[name='attachFiles["+rn+"]']").val("");
            $("input[name='attach_file_nm[" + rn + "]']").val("");
            objFile.replaceWith(objFile.clone(true));
            return;
        }
    }
    $("input[name='attach_file_nm[" + rn + "]']").val(file_name);
};



//파일명 추출후 업로드 가능 확장자인지 확인.
/**
 * @method
 * @name fn_getFileNm1
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getFileNm1 = function() {
    var temp = $("input[name='batScdaplExcelFiles[0]']").val();
    $("input[name='batScdaplExcelFilesNm[0]']").val(temp.substring(temp.lastIndexOf('\\') + 1));
    var file_name = temp.substring(temp.lastIndexOf('\\') + 1);
    var file = file_name.split(".");
    var extList = new Array("xls", "xlsx");
    var fileChk = 0;
    for (var i = 0; i < extList.length; i++) {
        if (file[file.length - 1].toLowerCase() == extList[i]) fileChk = fileChk + 1;
    }
    if (fileChk == 0) {
        alert("첨부 불가능한 파일입니다.");
        $("input[name='batScdaplExcelFiles[0]']").val("");
        $("input[name='batScdaplExcelFilesNm[0]']").val("");
    }
};



//Row 추가
/**
 * @method
 * @name fn_addRow
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_addRow = function() {
    var rowPlus = document.getElementById("tbl_file");
    var tr;
    var th;
    var td;
    var newRowNum = scwin.rownum + 1;

    //alert(rownum +";"+ newRowNum);
    if (scwin.rownum == 0) {
        rowPlus.deleteRow(0);
    }
    tr = rowPlus.insertRow();
    tr.addClass("last");
    td = tr.insertCell();
    td.addClass("dvs last");
    td.innerHTML = "<input type=\"checkbox\" name=\"chk\" id==\"chk\" size=\"1\" onClick='fn_fileChk(this);' />";

    //alert(td.innerHTML);
    //td.append(td);

    td = tr.insertCell();
    td.addClass("txt last long");
    td.innerHTML = "<input type=\"text\" name=\"attach_file_nm[" + scwin.rownum + "]\"  id=\"attach_file_nm\" readonly style=\"width: 300px;vertical-align:middle\" class=\"file_input_textbox\" /><div class=\"file_input_div\"><img src=\"/img/btn/btn_find.gif\" name=\"file_1\" class=\"file_input_img_btn\" alt=\"open\" /><input type=\"file\" name=\"attachFiles[" + scwin.rownum + "]\" style=\"width:95px; height:20;vertical-align:middle\" onchange=\"fn_getFileNm(" + scwin.rownum + ");\" class=\"file_input_hidden\" /></div>";

    //td.append(td);

    td = tr.insertCell();
    td.addClass("txt last long");
    td.innerHTML = "<input type=\"text\" name=\"file_coment\" class=\"txt inner\"/>";

    //alert(td.innerHTML);
    //td.append(td);


    scwin.rownum++;
    scwin.reNames();
};


//라디오버튼 text타입으로 값전달
/**
 * @method
 * @name fn_setAttach_chk
 * @description desc
 * @param {string} div desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setAttach_chk = function(div, val) {
    var frm = document.JLDINF05000;
    if (scwin.rownum == 1) {
        frm.attach_file_tp_cd.setValue(val);
    } else {
        frm.attach_file_tp_cd[div - 1].setValue(val);
    }
};



//Row 삭제
/**
 * @method
 * @name fn_delRow
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_delRow = function() {
    var rowPlus = document.getElementById("tbl_file");
    var chk_num = 0;

    //alert(rownum);

    if (scwin.rownum > 0) {
        $i = 0;
        $('input[name=chk]').each(function() {
            //alert($i);
            if ($(this).is(":checked")) {
                chk_num++;
                rowPlus.deleteRow($i);
                scwin.rownum--;
                $i = $i - 1;
                if (scwin.rownum == 0) {
                    var tr;
                    var th;
                    var td;
                    var newRowNum = scwin.rownum + 1;
                    tr = rowPlus.insertRow();
                    tr.addClass("last");
                    td = tr.insertCell();
                    td.colSpan = "3";
                    td.addClass("dvs last txc");
                    td.innerHTML = "업로드할 파일이 없습니다.";

                    //td.appendChild(td);

                }
                //input file 내용지우기

                /*var temp = $('input[name=attachFile]');
                temp[$i-1].select();
                document.selection.clear();*/
            }
            $i = $i + 1;
        });
        scwin.reNames();
        if (chk_num == 0) {
            alert("선택된 행이 없습니다.");
            return;
        }
    } else if (scwin.rownum < 1) {
        alert("삭제 할 행이 없습니다.");
    }
    document.getElementById("chk_all").setValue(0);
};



//전체체크
/**
 * @method
 * @name fn_fileAllCheck
 * @description desc
 * @param {string} frm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_fileAllCheck = function(frm) {
    var chk_all = frm.chk_all;
    if (scwin.rownum < 1 && chk_all.checked) {
        alert("체크 할 행이 없습니다.");
        chk_all.setValue(0);
        return;
    }
    if (chk_all.checked) {
        if (scwin.rownum == 1) {
            frm.chk.setValue(1);
        } else {
            for (var i = 0; i < scwin.rownum; i++) {
                frm.chk[i].setValue(1);
            }
        }
    } else {
        if (scwin.rownum == 1) {
            frm.chk.checked.setValue(0);
        } else {
            for (var i = 0; i < scwin.rownum; i++) {
                frm.chk[i].setValue(0);
            }
        }
    }
};
/**
 * @method
 * @name fn_fileChk
 * @description desc
 * @param {string} objChk desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_fileChk = function(objChk) {
    if (objChk.checked == false) {
        $('input[name=chk_all]')[0].setValue(0);
    } else {
        // 모두 체크 되었으면 전체도 체크.
        var chkboxCnt = $('input[name=chk]').length;
        var chkedCnt = 0;
        $('input[name=chk]').each(function() {
            if ($(this).is(":checked")) {
                chkedCnt++;
            }
        });

        // 체크된 것과 chk갯수가 동일하면..
        if (chkboxCnt == chkedCnt) {
            $('input[name=chk_all]')[0].setValue(1);
        } else {
            $('input[name=chk_all]')[0].setValue(0);
        }
    }
};




//저장시 파일 추가되어 있는지 확인
/**
 * @method
 * @name checkLineFile
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkLineFile = function() {
    for (var i = 0; i < 5; i++) {
        var fi = $("input[name='attach_file_nm[" + i + "]']").val();
        if (fi == "") {
            alert("첨부파일이 없습니다.\n첨부할 파일이 없으면 파일첨부를 삭제해 주세요");
            $("input[name='attach_file_nm[" + i + "]']").focus();
            return false;
        }
    }
    return true;
};
/**
 * @method
 * @name reNames
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.reNames = function() {
    $.each($("input:file"), function(i) {
        $(this).attr("name", "attachFiles[" + i + "]");
        $(this).attr("onchange", "fn_getFileNm(" + i + ");");
    });
    $.each($("#tbl_file").find("input[id='attach_file_nm']"), function(i) {
        $(this).attr("name", "attach_file_nm[" + i + "]");
    });
};



// 전체 첨부파일의 크기를 MB로 리턴한다.
/**
 * @method
 * @name sumAttachedFilesSize
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.sumAttachedFilesSize = function() {
    // 파일타입 객체 전체 select
    var all_files = $("input[type='file']");
    var totalSize = 0;
    for (var i = 0; i < all_files.length; i++) {
        if (all_files[i].files[0] != undefined) {
            var fileName = all_files[i].files[0].name;
            var fileSize = all_files[i].files[0].size;
            var fileExtension = fileName.split('.').pop();
            totalSize += fileSize;
        }
    }
    //alert("첨부파일 전체 크기 = " + (totalSize/(1024*1024)).toFixed(2));
    return (totalSize / (1024 * 1024)).toFixed(2);
};
